import * as THREE from 'three/webgpu';
import { mix, clamp, step, uv } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const buttonW = 2.6;
  const buttonH = 0.68;
  const cornerRadius = 0.08;
  const shadowDepth = 0.08;

  const geometry = createRoundedPlaneGeometry(buttonW, buttonH, cornerRadius, 64);
  const material = createGradientMaterial();
  const button = new THREE.Mesh(geometry, material);
  group.add(button);

  const shadowGeo = new THREE.PlaneGeometry(buttonW, buttonH);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.z = -shadowDepth;
  shadow.renderOrder = -1;
  group.add(shadow);

  addTextContent(group, ctx, buttonW, buttonH);

  group.scale.set(1.04, 1.04, 1.04);
  gsap.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  });

  setupInteractions(button, shadow);

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    gsap.killTweensOf([
      group.scale,
      button.position,
      button.scale,
      shadow.scale,
      material
    ]);
  };

  return group;
}

function createRoundedPlaneGeometry(w, h, radius, segments) {
  const geo = new THREE.PlaneGeometry(w, h, segments, segments);
  const pos = geo.attributes.position;
  const arr = pos.array;

  const halfW = w / 2;
  const halfH = h / 2;
  const cornerThreshX = halfW - radius;
  const cornerThreshY = halfH - radius;

  for (let i = 0; i < arr.length; i += 3) {
    let x = arr[i];
    let y = arr[i + 1];

    const absX = Math.abs(x);
    const absY = Math.abs(y);

    if (absX > cornerThreshX && absY > cornerThreshY) {
      const dx = absX - cornerThreshX;
      const dy = absY - cornerThreshY;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist > radius) {
        const scale = radius / dist;
        arr[i] = Math.sign(x) * (cornerThreshX + dx * scale);
        arr[i + 1] = Math.sign(y) * (cornerThreshY + dy * scale);
      }
    }
  }

  pos.needsUpdate = true;
  geo.computeVertexNormals();

  return geo;
}

function createGradientMaterial() {
  const col1 = new THREE.Color(0xff4450);
  const col2 = new THREE.Color(0xff2a38);
  const col3 = new THREE.Color(0xc1121f);

  const mat = new THREE.MeshStandardMaterial({
    metalness: 0.35,
    roughness: 0.5,
    clearcoat: 0.22,
    emissive: new THREE.Color(0xff2a38),
    emissiveIntensity: 1.6,
    transparent: false
  });

  const uvY = uv().y;
  const gradLower = mix(col1, col2, clamp(uvY * 2.0, 0, 1));
  const gradFull = mix(gradLower, col3, clamp((uvY - 0.5) * 2.0, 0, 1));

  mat.colorNode = gradFull;

  return mat;
}

